{"command":"python -c "
import compression.zstd as zstd, json, collections
path = r'C:\Users\13701\.dsh\sessions\--C-Users-13701-Documents-VibeCoding-StreamTranslator--\session-4f92771f-0754-4cff-8fd2-ff0f8cc76d0f\session.v4.jsonl.zstd'
with open(path, 'rb') as f:
    raw = zstd.decompress(f.read()).decode('utf-8', errors='replace')
lines = [json.loads(l) for l in raw.splitlines() if l.strip()]
print('Types:', collections.Counter(x.get('type') for x in lines))
for i, obj in enumerate(lines):
    t = obj.get('type')
    if t in ('user/message', 'assistant/message', 'message/user', 'message/assistant', 'turn/user', 'agent/message', 'chat/message') or 'message' in (t or '') or 'text' in (t or ''):
        if t == 'system/message':
            continue
        d = obj.get('data', {})
        print(f'--- [{i}] {t} ---')
        if isinstance(d, dict):
            # print text content concisely
            msg = d.get('message') or d
            if isinstance(msg, dict):
                role = msg.get('role')
                content = msg.get('content')
                if isinstance(content, str):
                    print(f'role={role}: {content[:2000]}')
                elif isinstance(content, list):
                    for part in content:
                        if isinstance(part, dict) and part.get('type') == 'text':
                            print(f'role={role} [text]: {part.get(\"text\", \"\")[:3000]}')
                        elif isinstance(part, dict):
                            print(f'role={role} [{part.get(\"type\")}]: {str(part)[:200]}')
                else:
                    print(str(d)[:500])
            else:
                print(str(d)[:500])
        else:
            print(str(d)[:500])
"","description":"Extract conversation messages from previous session"}

