import compression.zstd as zstd, json, collections
path = r'C:\Users\13701\.dsh\sessions\--C-Users-13701-Documents-VibeCoding-StreamTranslator--\session-4f92771f-0754-4cff-8fd2-ff0f8cc76d0f\session.v4.jsonl.zstd'
with open(path, 'rb') as f:
    raw = zstd.decompress(f.read()).decode('utf-8', errors='replace')
lines = [json.loads(l) for l in raw.splitlines() if l.strip()]
print('Types:', collections.Counter(x.get('type') for x in lines))
for i, obj in enumerate(lines):
    t = obj.get('type')
    if t and ('message' in t) and t != 'system/message':
        d = obj.get('data', {})
        print(f'=== [{i}] {t} ===')
        msg = d.get('message') if isinstance(d, dict) and 'message' in d else d
        if isinstance(msg, dict):
            role = msg.get('role')
            content = msg.get('content')
            if isinstance(content, str):
                print(f'role={role}:\n{content}')
            elif isinstance(content, list):
                for part in content:
                    if isinstance(part, dict) and part.get('type') == 'text':
                        txt = part.get('text', '')
                        print(f'role={role} [text]:\n{txt}')
                    elif isinstance(part, dict) and part.get('type') == 'tool_call':
                        print(f'role={role} [tool_call]: {part.get("name")}')
            else:
                print(str(d)[:500])
'@ | python -","description":"Extract user and assistant messages from previous session"}

