{"content":"using System.Windows;
using System.Windows.Media;

namespace StreamTranslator.App.Controls;

/// <summary>
/// 分段式声学 LED 电平仪，用于在主页演播控台实时呈现系统输出音量、
/// 峰值保持衰减与高电平告警区，替代传统细进度条。
/// </summary>
public sealed class SegmentedLevelMeter : FrameworkElement
{
    public static readonly DependencyProperty LevelProperty = DependencyProperty.Register(
        nameof(Level),
        typeof(double),
        typeof(SegmentedLevelMeter),
        new FrameworkPropertyMetadata(0d, FrameworkPropertyMetadataOptions.AffectsRender, OnLevelChanged));

    public static readonly DependencyProperty SegmentCountProperty = DependencyProperty.Register(
        nameof(SegmentCount),
        typeof(int),
        typeof(SegmentedLevelMeter),
        new FrameworkPropertyMetadata(28, FrameworkPropertyMetadataOptions.AffectsRender));

    public static readonly DependencyProperty IsSpeechActiveProperty = DependencyProperty.Register(
        nameof(IsSpeechActive),
        typeof(bool),
        typeof(SegmentedLevelMeter),
        new FrameworkPropertyMetadata(false, FrameworkPropertyMetadataOptions.AffectsRender));

    public static readonly DependencyProperty InactiveBrushProperty = DependencyProperty.Register(
        nameof(InactiveBrush),
        typeof(Brush),
        typeof(SegmentedLevelMeter),
        new FrameworkPropertyMetadata(new SolidColorBrush(Color.FromArgb(0x28, 0x80, 0x88, 0x94)), FrameworkPropertyMetadataOptions.AffectsRender));

    public static readonly DependencyProperty NormalBrushProperty = DependencyProperty.Register(
        nameof(NormalBrush),
        typeof(Brush),
        typeof(SegmentedLevelMeter),
        new FrameworkPropertyMetadata(new SolidColorBrush(Color.FromRgb(0x0F, 0x9D, 0x76)), FrameworkPropertyMetadataOptions.AffectsRender));

    public static readonly DependencyProperty WarmBrushProperty = DependencyProperty.Register(
        nameof(WarmBrush),
        typeof(Brush),
        typeof(SegmentedLevelMeter),
        new FrameworkPropertyMetadata(new SolidColorBrush(Color.FromRgb(0xD9, 0x77, 0x06)), FrameworkPropertyMetadataOptions.AffectsRender));

    public static readonly DependencyProperty PeakBrushProperty = DependencyProperty.Register(
        nameof(PeakBrush),
        typeof(Brush),
        typeof(SegmentedLevelMeter),
        new FrameworkPropertyMetadata(new SolidColorBrush(Color.FromRgb(0xC4, 0x2B, 0x1C)), FrameworkPropertyMetadataOptions.AffectsRender));

    private double _peakLevel;
    private long _lastPeakTick;

    public double Level
    {
        get => (double)GetValue(LevelProperty);
        set => SetValue(LevelProperty, value);
    }

    public int SegmentCount
    {
        get => (int)GetValue(SegmentCountProperty);
        set => SetValue(SegmentCountProperty, value);
    }

    public bool IsSpeechActive
    {
        get => (bool)GetValue(IsSpeechActiveProperty);
        set => SetValue(IsSpeechActiveProperty, value);
    }

    public Brush InactiveBrush
    {
        get => (Brush)GetValue(InactiveBrushProperty);
        set => SetValue(InactiveBrushProperty, value);
    }

    public Brush NormalBrush
    {
        get => (Brush)GetValue(NormalBrushProperty);
        set => SetValue(NormalBrushProperty, value);
    }

    public Brush WarmBrush
    {
        get => (Brush)GetValue(WarmBrushProperty);
        set => SetValue(WarmBrushProperty, value);
    }

    public Brush PeakBrush
    {
        get => (Brush)GetValue(PeakBrushProperty);
        set => SetValue(PeakBrushProperty, value);
    }

    public void ResetPeak()
    {
        _peakLevel = 0;
        _lastPeakTick = 0;
        InvalidateVisual();
    }

    private static void OnLevelChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
    {
        if (d is not SegmentedLevelMeter meter)
        {
            return;
        }

        var next = Math.Clamp((double)e.NewValue, 0d, 100d);
        var now = Environment.TickCount64;
        if (next <= 0.01d)
        {
            meter._peakLevel = 0d;
            meter._lastPeakTick = now;
            return;
        }

        if (next >= meter._peakLevel)
        {
            meter._peakLevel = next;
            meter._lastPeakTick = now;
        }
        else if (now - meter._lastPeakTick > 360)
        {
            // 超过保持窗口后平滑衰减峰值指示格
            meter._peakLevel = Math.Max(next, meter._peakLevel - 3.5d);
        }
    }

    protected override void OnRender(DrawingContext drawingContext)
    {
        base.OnRender(drawingContext);

        var width = ActualWidth;
        var height = ActualHeight;
        var count = Math.Max(8, SegmentCount);
        if (width <= 4 || height <= 2)
        {
            return;
        }

        const double gap = 3d;
        var segmentWidth = (width - gap * (count - 1)) / count;
        if (segmentWidth <= 1d)
        {
            segmentWidth = Math.Max(1d, width / count);
        }

        var clampedLevel = Math.Clamp(Level, 0d, 100d);
        var litCount = (int)Math.Round(clampedLevel / 100d * count);
        var peakIndex = _peakLevel > 1d
            ? Math.Clamp((int)Math.Round(_peakLevel / 100d * count) - 1, 0, count - 1)
            : -1;

        var radius = Math.Min(2d, segmentWidth * 0.35);
        var inactive = InactiveBrush;
        var normal = NormalBrush;
        var warm = WarmBrush;
        var peak = PeakBrush;

